use glob ; use prost_build ; type CompileResult = Result < () , std :: io :: Error > ; fn compile_company_protos () -> CompileResult { prost_build :: compile_protos (& ["proto/company_v1.proto"] , & ["proto/"]) } fn compile_vendored () -> CompileResult { let vendored_paths : Vec < String > = glob :: glob ("proto/vendored/**/*.proto") . expect ("Failed to glob files") . map (| x | x . unwrap () . display () . to_string ()) . collect () ; prost_build :: compile_protos (& vendored_paths , & ["proto/vendored" . to_owned ()]) } fn main () { if let Err (e) = compile_company_protos () { panic ! ("Failed to compile $Company protos:\n{}" , e) ; } if let Err (e) = compile_vendored () { panic ! ("Failed to compile vendored protos:\n{}" , e) ; } }